const crypto = require('crypto');

return await Promise.all(
  $input.all().map(async (item) => {
    const headers = item.json.headers ?? {};
    const timestamp = String(
      headers['x-lendloop-timestamp'] ?? headers['X-LendLoop-Timestamp'] ?? ''
    ).trim();

    const rawSigHeader = String(
      headers['x-lendloop-signature'] ?? headers['X-LendLoop-Signature'] ?? ''
    ).trim();
    const signature = rawSigHeader.startsWith('sha256=')
      ? rawSigHeader.slice('sha256='.length)
      : rawSigHeader;

    const secret = String(item.json.webhookSecret ?? '').trim();

    if (!timestamp) {
      throw new Error('Missing X-LendLoop-Timestamp header');
    }
    if (!signature) {
      throw new Error('Missing X-LendLoop-Signature header');
    }
    if (!secret) {
      throw new Error(
        'Missing webhookSecret (check $env.LENDLOOP_N8N_WEBHOOK_SECRET and N8N_BLOCK_ENV_ACCESS_IN_NODE=false)'
      );
    }

    const nowSec = Math.floor(Date.now() / 1000);
    if (Math.abs(nowSec - Number(timestamp)) > 300) {
      throw new Error('Webhook timestamp outside allowed window');
    }

    let rawBody;
    if (typeof item.json.rawBody === 'string') {
      rawBody = item.json.rawBody;
    } else if (item.binary?.data) {
      rawBody = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
    } else {
      rawBody = JSON.stringify(item.json.body ?? {});
    }

    const expected = crypto
      .createHmac('sha256', secret)
      .update(`${timestamp}.${rawBody}`)
      .digest('hex');

    const sigBuf = Buffer.from(signature, 'utf8');
    const expBuf = Buffer.from(expected, 'utf8');

    if (sigBuf.length !== expBuf.length || !crypto.timingSafeEqual(sigBuf, expBuf)) {
      throw new Error('Invalid HMAC signature');
    }

    const payload =
      typeof item.json.body === 'object' && item.json.body !== null
        ? item.json.body
        : JSON.parse(rawBody);

    return { json: payload };
  })
);

return $input.all().map((item) => {
  const data = item.json;
  const recipient = data.recipient ?? {};

  const messages = {
    request_created: `New borrow request for "${data.toolName}" (${data.startDate} to ${data.endDate}). Status: ${data.status}.`,
    request_approved: `Your borrow request for "${data.toolName}" (${data.startDate} to ${data.endDate}) was approved.`,
    request_declined: `Your borrow request for "${data.toolName}" (${data.startDate} to ${data.endDate}) was declined.`,
    loan_returned: `Return recorded for "${data.toolName}" (${data.startDate} to ${data.endDate}). Status: ${data.status}.`,
  };

  const body =
    messages[data.eventType] ??
    `Loan update (${data.eventType}) for "${data.toolName}" (${data.startDate} to ${data.endDate}). Status: ${data.status}.`;

  return {
    json: {
      idempotencyKey: data.idempotencyKey,
      eventType: data.eventType,
      recipientName: recipient.name ?? "Neighbor",
      recipientEmail: recipient.email ?? null,
      subject: `LendLoop: ${data.toolName} (${data.status})`,
      message: body,
    },
  };
});
